long long recursiveSolve(long long n, int step, const vector<long long>& a) {
    long long result = (step + 1LL) * (n / a[step]);
    n %= a[step];
    if (n == 0) return result;
    long long optionA = recursiveSolve(n, step - 1, a);
    long long optionB = step + 1 + recursiveSolve(a[step] - n, step - 1, a);
    return result + min(optionA, optionB);
}

