import java.util.*;

public class Main {
    public static long recursiveSolve(long n, int step, long[] a) {
        long result = (long)(step + 1) * (n / a[step]);
        n %= a[step];
        if (n == 0) return result;
        long optionA = recursiveSolve(n, step - 1, a);
        long optionB = step + 1 + recursiveSolve(a[step] - n, step - 1, a);
        return result + Math.min(optionA, optionB);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long[] a = new long[16];
        a[0] = 1;
        for (int i = 1; i < 16; i++) {
            a[i] = a[i - 1] * 10 + 1;
        }
        long n = sc.nextLong();
        System.out.println(recursiveSolve(n, 15, a));
        sc.close();
    }
}
